<script setup>
import {ref,computed} from 'vue';import FlowShell from './FlowShell.vue';import {state,writeState,resetState,navigate,back,note,confirm,actorList,actorKey,serverSwitchActor,serverOnline} from './app-state.js';const draft=ref({...state.settings});const actors=actorList();const currentActor=ref(actorKey());const actorLabel=computed(()=>(actors.find(a=>a.key===currentActor.value)||{}).label||'老人');const online=computed(()=>serverOnline());function switchActor(){uni.showActionSheet({itemList:actors.map(a=>a.label+'（'+a.role+'）'),success:async r=>{const target=actors[r.tapIndex];if(!target)return;if(await serverSwitchActor(target.key)){currentActor.value=target.key;uni.showModal({title:'已切换身份',content:'当前身份：'+target.label+'。老人端、家属端、景区端都已接本地后端，切换后按该身份读取数据。',showCancel:false,success:()=>uni.reLaunch({url:'/pages/'+({family:'family-view',scenic:'staff',official:'staff',admin:'staff'}[target.key]||'home')})})}}})}function save(){writeState('settings',draft.value);back()}function reset(){confirm('重置演示数据','将清空本机演示档案、授权、游览、记录和设置，是否继续？',()=>{resetState();uni.reLaunch({url:'/pages/welcome'})})}
function handlePageAction0(){uni.reLaunch({url:'/pages/home'})}

</script>
<template>
  <FlowShell class="paper-page paper-social" title="使用设置">
    <view class="paper-hero paper-contact-hero"><view class="paper-illustration"><image src="/static/refined/settings.png" mode="aspectFit"/></view><text class="paper-title">调成您用着舒服的样子</text><text class="paper-subtitle">阅读、语音和提问，都按您的习惯来</text></view>
    <view class="paper-card"><text class="paper-heading">显示与阅读</text><text class="paper-label">字号大小</text><view class="paper-segments" role="group" aria-label="字号大小"><button v-for="x in [['standard','标准'],['large','大字'],['huge','特大']]" :key="x[0]" :class="{'is-selected':draft.fontSize===x[0]}" :aria-pressed="draft.fontSize===x[0]" @click="draft.fontSize=x[0]">{{x[1]}}</button></view><view class="paper-inset"><text class="paper-label">阅读示例</text><text class="paper-reading-sample" :class="'sample-'+draft.fontSize">按自己的节奏，慢慢欣赏沿途风景。</text></view></view>
    <view class="paper-card"><text class="paper-heading">语音与提问</text><text class="paper-label">播放语速</text><view class="paper-segments" role="group" aria-label="播放语速"><button v-for="x in [['slow','慢速'],['normal','正常'],['fast','快速']]" :key="x[0]" :class="{'is-selected':draft.speechRate===x[0]}" :aria-pressed="draft.speechRate===x[0]" @click="draft.speechRate=x[0]">{{x[1]}}</button></view><text class="paper-label paper-section-label">提问方式</text><view class="paper-segments" role="group" aria-label="提问方式"><button v-for="x in [['voice','语音优先'],['text','文字优先']]" :key="x[0]" :class="{'is-selected':draft.inputMode===x[0]}" :aria-pressed="draft.inputMode===x[0]" @click="draft.inputMode=x[0]">{{x[1]}}</button></view><button class="paper-field" @click="note('语音服务尚未接入，仅保存设置。')"><view class="paper-disc paper-disc-warm"><image src="/static/outing/icons/speaker.svg"/></view><view class="paper-copy"><text class="paper-body">试听语音</text><text class="paper-label">点按试听，语音服务尚未接入</text></view><image class="paper-chevron" src="/static/outing/icons/back.svg"/></button></view>
    <view class="paper-card"><text class="paper-heading">联调身份</text><button class="paper-field" aria-label="切换身份" @click="switchActor"><view class="paper-disc"><image src="/static/outing/icons/person.svg"/></view><view class="paper-copy"><text class="paper-label">当前身份</text><text class="paper-value">{{actorLabel}}</text></view><text class="paper-link-label">切换身份</text></button><view class="paper-note"><image src="/static/outing/icons/info.svg"/><text>{{online?'已连接本地后端 8080，页面读取接口数据。':'未连接后端，当前使用本地演示数据。'}}</text></view></view>
    <view class="paper-card"><text class="paper-heading">使用帮助</text>
      <button class="paper-field" @click="note('点语音键提问；游览中可确认求助；从服务安排游览，从记录查看经历。','使用说明')"><view class="paper-disc"><image src="/static/outing/icons/info.svg"/></view><text class="paper-copy paper-body">使用说明</text><image class="paper-chevron" src="/static/outing/icons/back.svg"/></button>
      <button class="paper-field" @click="handlePageAction0"><view class="paper-disc"><image src="/static/outing/icons/person.svg"/></view><text class="paper-copy paper-body">老人端</text><image class="paper-chevron" src="/static/outing/icons/back.svg"/></button>
      <button class="paper-field" @click="navigate('family-view')"><view class="paper-disc"><image src="/static/outing/icons/people.svg"/></view><text class="paper-copy paper-body">家属端</text><image class="paper-chevron" src="/static/outing/icons/back.svg"/></button>
      <button class="paper-field" @click="navigate('staff')"><view class="paper-disc"><image src="/static/outing/icons/headset.svg"/></view><text class="paper-copy paper-body">景区端</text><image class="paper-chevron" src="/static/outing/icons/back.svg"/></button>
    </view>
    <view class="paper-actions"><button class="paper-secondary" @click="reset">重置本机数据</button><button class="paper-primary" @click="save">保存设置</button></view>
  </FlowShell>
</template>
<style src="./paper.css"></style>
